package com.careerpilot.modules.careerai.controller;
import com.careerpilot.modules.careerai.dto.CareerAiDtos.*;import com.careerpilot.modules.careerai.service.CareerAiService;import com.careerpilot.security.CurrentUser;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/career-ai")public class CareerAiController{private final CareerAiService service;public CareerAiController(CareerAiService service){this.service=service;}@PostMapping("/interview")public InterviewResponse interview(@Valid@RequestBody InterviewRequest request){return service.interview(CurrentUser.require(),request);}@PostMapping("/copilot")public CopilotResponse copilot(@Valid@RequestBody CopilotRequest request){return service.copilot(CurrentUser.require(),request);}}
